   if(!mirror||mirror.blocked)return{status:'error',message:'Finish the active operation in the main window.'};if(['select','edit','move'].includes(value.action.kind)&&![...(mirror.snapshot.project?.records??[]),...(mirror.snapshot.universe?.records??[])].some(r=>r.id===(value.action as {id:string}).id))return{status:'error',message:'This record is no longer active.'};if(value.action.kind==='create-event'){const calendar=mirror.snapshot.universe?.records.find(r=>r.recordType==='calendar');try{if(!calendar||calendar.recordType!=='calendar')throw new Error('Calendar unavailable.');elapsedPosition(value.action.date,calendar.data);}catch{return{status:'error',message:'This date is no longer available in the active universe calendar.'};}}if(value.action.kind==='timeline'){const calendar=mirror.snapshot.universe?.records.find(r=>r.recordType==='calendar');if(!validTimelineCalendar(value.action.value,calendar?.recordType==='calendar'?calendar.data:null))return{status:'error',message:'This timeline date is no longer available in the active universe calendar.'};}send({kind:'action',action:value.action,panelId:id});if(panelActionOpensMain(value.action))owner()?.focus();return result();
